using System;using System.IO;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace Sargon.Setup {
 public sealed class SetupWindow:Form {
  readonly string source;readonly TextBox log;readonly Button install;readonly CheckBox beta;CancellationTokenSource cancel=new CancellationTokenSource();bool working;bool finished;
  private void CompleteInstallation(bool remove){finished=true;Text="SARGON — paslaugos paruošimas baigtas";log.AppendText("\r\nŠIS DIEGIMO LANGAS BAIGĖ DARBĄ. Spauskite „Baigti ir grįžti į diegiklį“. Bazių atnaujinimo parengtį tikrinkite SARGON lange.\r\n");install.Text="Baigti ir grįžti į diegiklį";install.Enabled=true;install.Focus();}
  public SetupWindow(string package,bool allowBeta,string pin,bool remove=false,string requestId=null){source=package;Text="SARGON — paslaugos ir variklio diegimas";Width=830;Height=600;StartPosition=FormStartPosition.CenterScreen;Font=new System.Drawing.Font("Segoe UI",11);var note=new Label{Left=20,Top=20,Width=770,Height=110,Text="Bus įdiegta atskira Windows paslauga ir, jei trūksta, atsisiųstas oficialus ClamAV variklis. Reikalingas internetas; atsisiuntimas gali būti didelis. Vartotojo profilis ir karantinas neperkeliami. Tai bandomoji laida be patvirtintų Windows priėmimo bandymų."};beta=new CheckBox{Left=20,Top=140,Width=770,Height=60,Text="Sąmoningai diegti nepasirašytą bandomąją laidą (ne produkcinį leidimą)",Checked=allowBeta};install=new Button{Left=20,Top=210,Width=770,Height=50,Text="Įdiegti arba atnaujinti paslaugą ir paruošti variklį"};log=new TextBox{Left=20,Top=275,Width=770,Height=225,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right};Controls.AddRange(new Control[]{note,beta,install,log});install.Click+=async(s,e)=>{if(finished){DialogResult=DialogResult.OK;Close();return;}cancel.Dispose();cancel=new CancellationTokenSource();working=true;install.Enabled=beta.Enabled=false;bool selected=beta.Checked;try{Action<string> report=message=>{if(!IsDisposed)BeginInvoke((Action)(()=>log.AppendText(message+Environment.NewLine)));};await Task.Run(()=>{if(remove)Manager.Remove(report,requestId);else Manager.Install(source,selected,pin,report,cancel.Token,requestId);});CompleteInstallation(remove);}catch(Exception error){log.AppendText("DIEGIMAS NEPATVIRTINTAS: "+SargasPC.Data.Clean(error.Message)+"\r\n"+SargasPC.Data.Diagnostic(error)+Environment.NewLine);install.Enabled=beta.Enabled=true;}finally{working=false;}};FormClosing+=(s,e)=>{if(finished){DialogResult=DialogResult.OK;return;}if(working){e.Cancel=true;cancel.Cancel();log.AppendText("Vyksta diegimas. Palaukite jo pabaigos; langas neuždaromas vykstant pakeitimams."+Environment.NewLine);}};if(remove){Text="SARGON — paslaugos pašalinimas";install.Text="Pašalinti atskirą Windows paslaugą";beta.Visible=false;note.Text="Bus sustabdyta ir pašalinta atskira SARGON Windows paslauga. Jos stebėjimas sustos visoms paskyroms. Žurnalai, duomenys ir atkuriamos kopijos automatiškai netrinami.";}}
 }
 static class SetupProgram {
  [STAThread]static int Main(string[] args){if(Environment.OSVersion.Platform!=PlatformID.Win32NT)return 2;return WindowsMain(args);}
  [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]static int WindowsMain(string[] args){try{Manager.RequireAdmin();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(Array.IndexOf(args,"--scan-settings")>=0){using(var scan=new PcScanWindow())Application.Run(scan);return 0;}if(Array.IndexOf(args,"--update-databases")>=0){using(var update=new DatabaseUpdateWindow())Application.Run(update);return 0;}string source=AppDomain.CurrentDomain.BaseDirectory;int index=Array.IndexOf(args,"--package");if(index>=0&&index+1<args.Length)source=Path.GetFullPath(args[index+1]);string pin="";index=Array.IndexOf(args,"--publisher");if(index>=0&&index+1<args.Length)pin=args[index+1];string requestId=null;index=Array.IndexOf(args,"--request");if(index>=0&&index+1<args.Length)requestId=args[index+1];using(var window=new SetupWindow(source,Array.IndexOf(args,"--allow-unsigned-beta")>=0,pin,Array.IndexOf(args,"--uninstall")>=0,requestId)){Application.Run(window);return window.DialogResult==DialogResult.OK?0:1;}}catch(Exception error){MessageBox.Show("Diegimas nepatvirtintas: "+SargasPC.Data.Diagnostic(error));return 1;}}
 }
}
namespace Sargon.Setup {
 public sealed class DatabaseUpdateWindow:Form {
  readonly TextBox log=new TextBox();readonly Button run=new Button();readonly CheckBox battery=new CheckBox();readonly CancellationTokenSource cancel=new CancellationTokenSource();bool working;
  public DatabaseUpdateWindow(){Text="SARGON — bendrų bazių atnaujinimas";Width=840;Height=620;MinimumSize=new System.Drawing.Size(780,550);Font=new System.Drawing.Font("Segoe UI",11);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),ColumnCount=1,RowCount=4};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,130));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,75));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,60));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));var note=new Label{Dock=DockStyle.Fill,Text="Paslauga atsisiųs oficialias ClamAV bazes ir tikrins neutralų failą. Gali būti atlikta anksčiau nuostatose pasirinkta EICAR kontrolė. Reikia interneto; pirmas atsisiuntimas gali būti didelis. Darbas laukia dabartinės patikros pabaigos, gali apkrauti diską ir CPU. Langas nuolatinių energijos nuostatų nekeičia."};battery.Dock=DockStyle.Fill;battery.Text="Vieną šį atnaujinimą leisti ir naudojant bateriją / kai maitinimo būsena nežinoma";run.Dock=DockStyle.Fill;run.Text="Užsakyti bazių atnaujinimą dabar";log.Dock=DockStyle.Fill;log.Multiline=true;log.ReadOnly=true;log.ScrollBars=ScrollBars.Vertical;layout.Controls.Add(note,0,0);layout.Controls.Add(battery,0,1);layout.Controls.Add(run,0,2);layout.Controls.Add(log,0,3);Controls.Add(layout);run.Click+=async(s,e)=>{working=true;run.Enabled=battery.Enabled=false;bool allow=battery.Checked;try{await Task.Run(()=>Manager.RequestDatabaseUpdate(allow,message=>{if(!IsDisposed)BeginInvoke((Action)(()=>log.AppendText(message+Environment.NewLine)));},cancel.Token));run.Text="Baigta — bazės ir neutrali kontrolė patvirtintos";}catch(Exception error){log.AppendText("ATNAUJINIMAS NEPATVIRTINTAS: "+SargasPC.Data.Clean(error.Message)+"\r\nUžklausa gali likti paslaugos eilėje. Būseną tikrinkite bendros parengties lange.\r\n");}finally{working=false;}};FormClosing+=(s,e)=>{if(working){e.Cancel=true;cancel.Cancel();log.AppendText("Baigiamas tik šio lango laukimas. Paslaugai perduota užklausa dėl to neatšaukiama.\r\n");}};FormClosed+=(s,e)=>cancel.Dispose();}
 }
}
